{
  "incident_detected": false,
  "root_cause_hypothesis": "The headline decline is consistent with normal variation and the prior year's March-to-May pattern, rather than evidence of a broad Romanian card-usage decline. Total card spending and active users both increased; spending simply grew more slowly than the active-user denominator. The data do not establish a causal explanation.",
  "supporting_metrics": [
    {
      "name": "Romania monthly card spend per active user, March versus May 2026",
      "baseline_value": 319.548121,
      "anomaly_value": 312.602723,
      "unit": "EUR/user",
      "sql": "SELECT a.month, sum(card_spend_eur)/count(DISTINCT CASE WHEN is_active THEN a.user_id END) spend_per_active FROM fct_activity_monthly a JOIN dim_users u USING(user_id) WHERE u.country='RO' GROUP BY 1 ORDER BY 1;"
    },
    {
      "name": "Romania monthly total card spend, March versus May 2026",
      "baseline_value": 1752082.35,
      "anomaly_value": 1888745.65,
      "unit": "EUR",
      "sql": "SELECT a.month, sum(card_spend_eur) spend FROM fct_activity_monthly a JOIN dim_users u USING(user_id) WHERE u.country='RO' GROUP BY 1 ORDER BY 1;"
    },
    {
      "name": "Romania monthly active users, March versus May 2026",
      "baseline_value": 5483,
      "anomaly_value": 6042,
      "unit": "count",
      "sql": "SELECT a.month, count(DISTINCT CASE WHEN is_active THEN a.user_id END) active_users FROM fct_activity_monthly a JOIN dim_users u USING(user_id) WHERE u.country='RO' GROUP BY 1 ORDER BY 1;"
    },
    {
      "name": "Romania March-to-May card spend per active user relative change, 2025 versus 2026",
      "baseline_value": -0.02057,
      "anomaly_value": -0.021735,
      "unit": "fraction",
      "sql": "WITH m AS (SELECT a.month,sum(card_spend_eur)/count(DISTINCT CASE WHEN is_active THEN a.user_id END) spa FROM fct_activity_monthly a JOIN dim_users u USING(user_id) WHERE country='RO' GROUP BY 1), changes AS(SELECT month,spa/lag(spa,2) OVER(ORDER BY month)-1 change FROM m) SELECT month,change FROM changes WHERE month IN ('2025-05-01','2026-05-01');"
    },
    {
      "name": "Romania historical two-month card spend per active user change standard deviation, January 2025–February 2026",
      "baseline_value": 0.09095,
      "anomaly_value": null,
      "unit": "fraction",
      "sql": "WITH m AS (SELECT a.month,sum(card_spend_eur)/count(DISTINCT CASE WHEN is_active THEN a.user_id END) spa FROM fct_activity_monthly a JOIN dim_users u USING(user_id) WHERE country='RO' GROUP BY 1), changes AS(SELECT month,spa/lag(spa,2) OVER(ORDER BY month)-1 change FROM m) SELECT stddev_samp(change) sd_change FROM changes WHERE month BETWEEN '2025-01-01' AND '2026-02-01';"
    }
  ],
  "recommended_action": "NO_ACTION_NOISE",
  "reasoning_summary": "Romanian spend per active user fell from EUR 319.548121 in March to EUR 312.602723 in May, a relative change of -0.021735. This closely matches the prior year's March-to-May change of -0.02057 and is smaller than the historical two-month change standard deviation of 0.09095. Meanwhile, total card spend rose from EUR 1752082.35 to EUR 1888745.65 and active users increased from 5483 to 6042. There is no compelling evidence of a usage incident; monitor rather than intervene, noting that the active-user denominator includes top-up-only users."
}
